"""One-time migration from the existing static page to the approved app shell."""
from pathlib import Path
import re
root=Path(__file__).resolve().parents[3]
p=root/'style-atlas/dist/index.html';s=p.read_text()
assert 'app-sidebar' not in s,'Migration already applied'
form=s[s.index('<form id="briefForm"'):s.index('</form>',s.index('<form id="briefForm"'))+7]
workflow=s[s.index('<section class="workflow"'):s.index('<section id="biblioteca"')]
library=s[s.index('<section id="biblioteca"'):s.index('<section id="myProject"')]
project=s[s.index('<section id="myProject"'):s.index('<section class="closing"')]
closing=s[s.index('<section class="closing"'):s.index('</main>')]
dialogs=s[s.index('<div id="compareBar"'):s.index('<script src="site-ui.js"')]
svg=lambda path:f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{path}</svg>'
icons={'library':svg('<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>'),'brief':svg('<rect x="3" y="4" width="18" height="16" rx="2"/><path d="m10 8 6 4-6 4Z"/>'),'help':svg('<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3v2M13 17h.01"/>')}
nav=''.join(f'<button type="button" data-app-view="{key}"'+(' id="projectNav"' if key=='brief' else '')+f'>{icons[key]}<span>{label}</span></button>' for key,label in [('library','Estilos'),('brief','Meu vídeo'),('help','Como usar')])
mobile=''.join(f'<button type="button" data-app-view="{key}">{icons[key]}<span>{label}</span></button>' for key,label in [('library','Estilos'),('brief','Meu vídeo'),('help','Ajuda')])
library=re.sub(r'<div class="section-head">.*?</div>\s*<div class="controls">','<div class="section-head"><div><h1 id="libraryTitle" tabindex="-1">Encontre o visual do seu vídeo.</h1><p>720 estilos · 18 categorias</p></div><button id="openBrief" class="outline">Minha escolha · <span id="chosenCount">0</span>/10</button></div><div class="controls">',library,count=1,flags=re.S)
category='<label class="category-menu" for="familySelect"><span id="categoryLabel" class="sr">Categoria</span><select id="familySelect" aria-label="Escolher categoria"></select></label>'
library=library.replace('<details class="extra-filters">',category+'<div class="filter-chips"><button id="allFilter" class="outline" aria-pressed="true">Todos</button><button id="videoFilter" class="outline" aria-pressed="false">▷ Com vídeo</button></div><details class="extra-filters">',1)
library=re.sub(r'<div class="category-toolbar">.*?</div>','',library,count=1,flags=re.S)
library=library.replace('<button id="newFilter"','<button hidden id="newFilter"')
library=library.replace('Abra “Ver direção” para examinar a imagem e os recursos.','Abra um estilo para explorar a sequência.')
project=project.replace('id="projectTitle"','id="projectTitle" tabindex="-1"')
brief='''<dialog id="briefDialog" aria-labelledby="briefTitle" class="brief-workspace"><button class="brief-back" type="button" data-close>← Voltar à biblioteca</button><header class="brief-heading"><h1 id="briefTitle" tabindex="-1">Seu próximo vídeo</h1></header><nav class="brief-steps" aria-label="Preparar o pedido"><button type="button" data-brief-stage="styles">1 <span>Estilos</span></button><button type="button" data-brief-stage="briefing">2 <span>Briefing</span></button><button type="button" data-brief-stage="review">3 <span>Revisar pedido</span></button></nav><div class="brief-workspace-grid"><section class="brief-editor">'''+form+'''<div id="handoff" hidden><h2 id="handoffTitle" tabindex="-1">Pedido pronto para levar ao ChatGPT</h2><p id="handoffMessage" class="small"></p><dl id="requestSummary" class="request-summary"></dl><h3>Materiais para enviar</h3><ul id="summaryMaterials" class="summary-materials"></ul><p class="small">Anexe os arquivos na conversa do ChatGPT.</p><div class="delivery-summary"><strong>Primeiro: roteiro → moodboard → storyboard → amostra de 10 s</strong><p>Você aprova os visuais antes da amostra e do vídeo completo.</p></div><details id="promptDetails"><summary>Ver pedido completo</summary><label class="sr" for="promptOutput">Pedido completo para produção</label><textarea id="promptOutput" rows="9" readonly></textarea></details><div class="actions"><button id="copyPrompt" class="primary">Copiar pedido</button><a href="https://chatgpt.com/" target="_blank" rel="noopener" class="button outline" id="chatLink">Abrir ChatGPT ↗</a></div><p id="handoffHelp" class="small">Copie o pedido, abra o ChatGPT e envie. O site não inicia uma geração automaticamente.</p><div class="handoff-secondary"><button id="handoffMaterials" type="button" class="text-button">Conferir todos os materiais</button><button type="button" class="text-button" data-app-view="project">Já estou produzindo: acompanhar</button></div></div></section><aside class="brief-preview"><div id="briefVisual"></div><details class="chosen-styles"><summary id="selectionSummary">Estilos escolhidos</summary><div id="selectionList" class="selection-list"></div></details><button id="addMoreStyles" type="button" class="outline">+ Combinar estilos · 0/10</button></aside></div></dialog>'''
start=dialogs.index('<dialog id="briefDialog"');end=dialogs.index('<dialog id="fontDialog"')
dialogs=dialogs[:start]+brief+dialogs[end:]
dialogs+='''<dialog id="sequenceDialog" aria-labelledby="sequenceTitle"><header><h2 id="sequenceTitle"></h2><button type="button" data-close aria-label="Fechar quadro ampliado">×</button></header><img id="sequenceImage" alt=""><p id="sequenceCaption"></p><div class="sequence-navigation"><button type="button" id="sequencePrev">← Anterior</button><span id="sequencePosition"></span><button type="button" id="sequenceNext">Próximo →</button></div><button type="button" class="outline" id="sequenceDownload">↓ Baixar este quadro em PNG</button></dialog>'''
head=s[:s.index('<body>')].replace('<link rel="stylesheet" href="styles.css">','<link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="app-shell.css">')
body='<body data-view="library"><a class="skip-link" href="#libraryTitle">Pular para os estilos</a><aside class="app-sidebar"><a class="app-brand" href="#biblioteca" data-app-view="library" aria-label="GDA Vídeos"><b>gda</b><span>Vídeos</span></a><nav aria-label="Navegação principal">'+nav+'</nav><p class="sidebar-note">Crie com suas contas e ferramentas.</p></aside><div class="app-main"><main>'+library+project+'<section id="appHelp"><h1 tabindex="-1">Como criar seu vídeo</h1>'+workflow+closing+'</section></main><footer class="app-footer"><a id="researchLink" href="research.html">Pesquisa e critérios ↗</a><span>GDA Vídeos · Conceitos visuais. Aprovação por etapa.</span><a href="catalog.json" download>Baixar catálogo</a></footer></div><div id="selectionTray" class="selection-tray" hidden><div id="trayImages"></div><strong id="trayCount"></strong><button type="button" class="text-button" data-app-view="brief">Ajustar combinação</button><button type="button" class="primary" data-app-view="brief">Preparar pedido →</button></div><nav class="mobile-app-nav" aria-label="Navegação mobile">'+mobile+'</nav>'+dialogs+'<script src="site-ui.js"></script><script src="workflow.js"></script><script src="gallery-views.js"></script><script src="app-shell.js"></script><script src="app.js"></script></body></html>'
p.write_text(head+body)
print('Static app shell installed; original input IDs and workflow controls preserved')
